import os
import numpy as np
import pandas as pd
from sklearn.metrics import roc_auc_score
import torch
import torch.nn as nn
import torch.optim as optim
from torchvision import transforms, models
from PIL import Image
import warnings

warnings.filterwarnings("ignore")


# Suppress all progress bars
def disable_tqdm():
    pass


os.makedirs("./submission", exist_ok=True)


def get_image_path(img_id):
    """Get paths for given image IDs"""
    # Try direct filename pattern based on sample_submission
    base_pattern = f"images/{img_id}.jpg"
    if os.path.exists(f"./input/{base_pattern}"):
        return f"./input/{base_pattern}"

    # Try input/images folder
    dir_path = "./input/images/"
    if os.path.exists(dir_path):
        files = [
            f
            for f in os.listdir(dir_path)
            if f.startswith("Test_") or img_id in f.lower()
        ]
        for f in files:
            if img_id in f.lower() and f.endswith(".jpg"):
                return os.path.join(dir_path, f)

    # Fallback to find any jpg with this ID
    dir_path = "./input/"
    if os.path.exists(dir_path):
        subdirs = [
            d for d in os.listdir(dir_path) if os.path.isdir(os.path.join(dir_path, d))
        ]
        for subdir in subdirs:
            if subdir == "images":
                files = [
                    f
                    for f in os.listdir(os.path.join(dir_path, subdir))
                    if img_id in f.lower() and f.endswith(".jpg")
                ]
                if files:
                    return os.path.join(dir_path, subdir, files[0])

    return None


def load_data():
    df_train = pd.read_csv("./input/train.csv")
    df_test = pd.read_csv("./input/test.csv")
    sample_sub = pd.read_csv("./input/sample_submission.csv")

    feature_cols = ["healthy", "rust", "scab", "multiple_diseases"]

    train_ids = df_train["image_id"].dropna().tolist()
    train_paths = []
    for pid in train_ids:
        pth = get_image_path(pid)
        if pth:
            train_paths.append(pth)
        else:
            print(f"Warning: Missing image for train_id: {pid}")

    test_ids = df_test["image_id"].tolist()
    test_paths = []
    for pid in test_ids:
        pth = get_image_path(pid)
        if pth:
            test_paths.append(pth)
        else:
            print(f"Warning: Missing image for test_id: {pid}")

    return df_train, df_test, train_paths, test_paths, feature_cols, sample_sub


try:
    df_train, df_test, train_paths, test_paths, feature_cols, sample_sub = load_data()
except Exception as e:
    raise e

print(f"Training images: {len(train_paths)}, Test images: {len(test_paths)}")

transform = transforms.Compose(
    [
        transforms.Resize((256, 224)),
        transforms.ToTensor(),
        transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225]),
    ]
)

device = torch.device("cuda:0" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")


class PlantDataset(torch.utils.data.Dataset):
    def __init__(self, paths, labels, transform=None):
        self.paths = paths
        self.labels = labels
        self.transform = transform

    def __len__(self):
        return len(self.paths)

    def __getitem__(self, idx):
        try:
            img = Image.open(self.paths[idx]).convert("RGB")
        except Exception as ex:
            print(f"Failed to open image {idx}: {ex}")
            return None

        if self.transform:
            img = self.transform(img)
        label = torch.FloatTensor(self.labels[idx])
        return img, label


train_dataset = PlantDataset(
    train_paths,
    df_train[feature_cols].values.astype(float).tolist(),
    transform=transform,
)

val_size = int(0.1 * len(train_dataset))
if val_size < 1:
    val_size = 1
val_idx = np.random.permutation(len(train_dataset))[:val_size]
train_idx = np.random.permutation(len(train_dataset))[val_size:]

train_set = torch.utils.data.Subset(train_dataset, list(train_idx))
val_set = torch.utils.data.Subset(train_dataset, list(val_idx))

train_loader = torch.utils.data.DataLoader(
    train_set, batch_size=32, shuffle=True, num_workers=0
)
val_loader = torch.utils.data.DataLoader(
    val_set, batch_size=32, shuffle=False, num_workers=0
)

test_dataset = PlantDataset(test_paths, [0.0] * len(test_paths), transform=transform)
test_loader = torch.utils.data.DataLoader(
    test_dataset, batch_size=32, shuffle=False, num_workers=0
)

model_name = "resnet50"
model = models.resnet50(weights=models.ResNet50_Weights.IMAGENET1K_V1)
num_features = 2048
fc = nn.Sequential(
    nn.Dropout(0.5),
    nn.Linear(num_features, 512),
    nn.ReLU(),
    nn.Dropout(0.3),
    nn.Linear(512, len(feature_cols)),
)
model.fc = fc

model = model.to(device)

criterion = nn.BCEWithLogitsLoss(reduction="none")
optimizer = optim.Adam(model.parameters(), lr=0.001, weight_decay=1e-5)

patience = 15
epochs = 50
patience_counter = 0
best_val_auc = 0
best_model_state = None

for epoch in range(1, epochs + 1):
    model.train()
    running_loss = 0.0
    for inputs, labels in train_loader:
        inputs = inputs.to(device)
        labels = labels.to(device)

        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels).sum()
        loss.backward()
        optimizer.step()
        running_loss += loss.item()

    val_probs_list = []
    val_labels_list = []

    model.eval()
    with torch.no_grad():
        for inputs, labels in val_loader:
            inputs = inputs.to(device)
            outputs = model(inputs)
            probs_batch = torch.sigmoid(outputs).cpu().numpy()

            for i in range(probs_batch.shape[0]):
                for j in range(probs_batch.shape[1]):
                    val_probs_list.append(probs_batch[i, j])
                    val_labels_list.append(float(labels[i, j]))

    val_probs_np = np.array(val_probs_list)
    val_labels_np = np.array(val_labels_list).reshape(-1, len(feature_cols))

    if len(val_labels_np) > 0:
        auc_per_class = roc_auc_score(val_labels_np.T, val_probs_np, average=None)
        mean_val_auc = np.mean(auc_per_class)

        if mean_val_auc > best_val_auc:
            best_val_auc = mean_val_auc
            patience_counter = 0
            best_model_state = {k: v.cpu() for k, v in model.state_dict().items()}
        else:
            patience_counter += 1
            if patience_counter >= patience:
                break

    print(
        f"Epoch [{epoch}/{epochs}], Loss: {running_loss/len(train_loader):.4f}, Val AUC: {mean_val_auc:.4f}"
    )

model.load_state_dict(best_model_state)
print("\nLoaded best model")

test_preds_np = []
with torch.no_grad():
    for inputs, _ in test_loader:
        inputs = inputs.to(device)
        outputs = model(inputs)
        probs_batch = torch.sigmoid(outputs).cpu().numpy()
        for row in probs_batch:
            for val in row:
                test_preds_np.append(val)

test_preds_array = np.array(test_preds_np).reshape(len(test_paths), len(feature_cols))

if os.path.exists("./input/sample_submission.csv"):
    sample_sub = pd.read_csv("./input/sample_submission.csv")
else:
    sample_sub = pd.DataFrame(columns=["image_id"] + feature_cols)

submit_df = pd.DataFrame(
    {
        "image_id": df_test["image_id"],
        **{col: test_preds_array[:, i] for i, col in enumerate(feature_cols)},
    }
)

submit_df.to_csv("./submission/submission.csv", index=False)
print("\nSubmission saved at ./submission/submission.csv")
print(f"Best Validation Mean Column-wise ROC AUC: {best_val_auc:.4f}")
